-- Biblioteca Municipal SaaS: pacote aditivo de operação, governança e rastreabilidade.

create table if not exists public.bib_bloqueios(
 id bigint generated by default as identity primary key, tenant_id uuid not null default app_private.current_tenant_id(), leitor_id integer not null references public.bib_leitores(id), motivo text not null, inicio timestamptz not null default now(), fim timestamptz, ativo boolean not null default true, criado_por integer, resolvido_por integer, resolvido_em timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists bib_bloqueios_leitor_ativo_idx on public.bib_bloqueios(tenant_id,leitor_id,ativo);
create table if not exists public.bib_auditoria(
 id bigint generated by default as identity primary key, tenant_id uuid not null default app_private.current_tenant_id(), usuario_id integer, acao text not null, entidade text not null, entidade_id text, dados jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()
);
create index if not exists bib_auditoria_entidade_idx on public.bib_auditoria(tenant_id,entidade,entidade_id,created_at desc);
create table if not exists public.bib_inventarios(
 id bigint generated by default as identity primary key, tenant_id uuid not null default app_private.current_tenant_id(), nome text not null, escopo jsonb not null default '{}'::jsonb, status text not null default 'ABERTO' check(status in('ABERTO','EM_EXECUCAO','CONCLUIDO','CANCELADO')), iniciado_por integer not null, iniciado_em timestamptz not null default now(), concluido_em timestamptz, created_at timestamptz not null default now()
);
create table if not exists public.bib_inventario_itens(
 id bigint generated by default as identity primary key, tenant_id uuid not null default app_private.current_tenant_id(), inventario_id bigint not null references public.bib_inventarios(id) on delete cascade, exemplar_id integer not null references public.bib_exemplares(id), lido_em timestamptz, lido_por integer, codigo_informado text, situacao_encontrada text, observacao text, divergente boolean not null default false, unique(inventario_id,exemplar_id)
);
create table if not exists public.bib_documentos(
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null default app_private.current_tenant_id(), entidade text not null check(entidade in('LIVRO','EXEMPLAR','EMPRESTIMO','DEVOLUCAO','LEITOR','INVENTARIO','AQUISICAO','DOACAO','BAIXA','EVENTO')), entidade_id text not null, nome_arquivo text not null, storage_path text not null unique, mime_type text not null, tamanho_bytes bigint not null check(tamanho_bytes>0 and tamanho_bytes<=26214400), enviado_por integer not null, created_at timestamptz not null default now()
);
create table if not exists public.bib_notificacoes(
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null default app_private.current_tenant_id(), usuario_id integer not null, tipo text not null, titulo text not null, mensagem text not null, prioridade text not null default 'normal' check(prioridade in('normal','alta','critica')), entidade text, entidade_id text, lida_em timestamptz, created_at timestamptz not null default now()
);
create index if not exists bib_notificacoes_usuario_idx on public.bib_notificacoes(tenant_id,usuario_id,lida_em,created_at desc);

alter table public.bib_bloqueios enable row level security; alter table public.bib_auditoria enable row level security; alter table public.bib_inventarios enable row level security; alter table public.bib_inventario_itens enable row level security; alter table public.bib_documentos enable row level security; alter table public.bib_notificacoes enable row level security;

do $$ declare t text; begin foreach t in array array['bib_bloqueios','bib_auditoria','bib_inventarios','bib_inventario_itens','bib_documentos','bib_notificacoes'] loop execute format('drop policy if exists %I on public.%I',t||'_anon',t); execute format('create policy %I on public.%I for all to anon using(false) with check(false)',t||'_anon',t); execute format('drop policy if exists %I on public.%I',t||'_tenant',t); execute format('create policy %I on public.%I for select to authenticated using(tenant_id=app_private.current_tenant_id())',t||'_tenant',t); end loop; end $$;
grant select on public.bib_bloqueios,public.bib_auditoria,public.bib_inventarios,public.bib_inventario_itens,public.bib_documentos,public.bib_notificacoes to authenticated;

create or replace function public.bib_registrar_auditoria(p_acao text,p_entidade text,p_entidade_id text,p_dados jsonb default '{}'::jsonb) returns bigint language plpgsql security definer set search_path=pg_catalog,public,app_private as $$ declare x bigint; begin insert into public.bib_auditoria(tenant_id,usuario_id,acao,entidade,entidade_id,dados) values(app_private.current_tenant_id(),app_private.current_user_id(),p_acao,p_entidade,p_entidade_id,coalesce(p_dados,'{}'::jsonb)) returning id into x; return x; end; $$;
grant execute on function public.bib_registrar_auditoria(text,text,text,jsonb) to authenticated;

create or replace function public.bib_obter_configuracao() returns jsonb language sql security invoker set search_path=pg_catalog,public,app_private as $$ select to_jsonb(c) from public.bib_configuracoes c where c.tenant_id=app_private.current_tenant_id() limit 1; $$;
grant execute on function public.bib_obter_configuracao() to authenticated;
create or replace function public.bib_salvar_configuracao(p_nome_biblioteca text,p_prazo_padrao integer,p_prazo_maximo integer,p_renovacoes integer,p_limite integer,p_dias_alerta integer,p_permite_reserva boolean) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,app_private as $$ declare x public.bib_configuracoes; uid integer:=app_private.current_user_id(); tid uuid:=app_private.current_tenant_id(); begin if not exists(select 1 from public.usuarios u where u.id=uid and u.perfil in('ADMIN','BIBLIOTECARIO','BIBLIOTECARIO_RESPONSAVEL')) then raise exception 'Sem permissão para configurar a Biblioteca' using errcode='42501'; end if; insert into public.bib_configuracoes(id,tenant_id,nome_biblioteca,prazo_padrao_dias,prazo_maximo_dias,renovacoes_maximas,limite_livros_por_leitor,dias_alerta_atraso,permite_reserva,updated_at) values(1,tid,coalesce(nullif(btrim(p_nome_biblioteca),''),'Biblioteca Municipal'),greatest(1,p_prazo_padrao),greatest(p_prazo_padrao,p_prazo_maximo),greatest(0,p_renovacoes),greatest(1,p_limite),greatest(0,p_dias_alerta),coalesce(p_permite_reserva,false),now()) on conflict(id) do update set nome_biblioteca=excluded.nome_biblioteca,prazo_padrao_dias=excluded.prazo_padrao_dias,prazo_maximo_dias=excluded.prazo_maximo_dias,renovacoes_maximas=excluded.renovacoes_maximas,limite_livros_por_leitor=excluded.limite_livros_por_leitor,dias_alerta_atraso=excluded.dias_alerta_atraso,permite_reserva=excluded.permite_reserva,updated_at=now() returning * into x; perform public.bib_registrar_auditoria('CONFIGURACAO_ATUALIZADA','CONFIGURACAO',x.id::text,to_jsonb(x)); return to_jsonb(x); end; $$;
revoke execute on function public.bib_salvar_configuracao(text,integer,integer,integer,integer,integer,boolean) from public,anon; grant execute on function public.bib_salvar_configuracao(text,integer,integer,integer,integer,integer,boolean) to authenticated;

create or replace function public.bib_registrar_reserva(p_livro_id integer,p_leitor_id integer,p_observacoes text default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,app_private as $$ declare x public.bib_reservas; cfg public.bib_configuracoes; uid integer:=app_private.current_user_id(); tid uuid:=app_private.current_tenant_id(); begin select * into cfg from public.bib_configuracoes where tenant_id=tid limit 1; if not coalesce(cfg.permite_reserva,false) then raise exception 'Reservas não estão habilitadas para esta Biblioteca' using errcode='42501'; end if; if exists(select 1 from public.bib_bloqueios where tenant_id=tid and leitor_id=p_leitor_id and ativo and (fim is null or fim>=now())) then raise exception 'Leitor bloqueado para reservas' using errcode='42501'; end if; if not exists(select 1 from public.bib_leitores where id=p_leitor_id and tenant_id=tid and status='ATIVO') then raise exception 'Leitor não encontrado ou inativo' using errcode='P0002'; end if; if exists(select 1 from public.bib_reservas where tenant_id=tid and livro_id=p_livro_id and leitor_id=p_leitor_id and status in('ATIVA','AGUARDANDO_RETIRADA')) then raise exception 'Leitor já possui reserva ativa para esta obra' using errcode='23505'; end if; insert into public.bib_reservas(tenant_id,livro_id,leitor_id,status,observacoes) values(tid,p_livro_id,p_leitor_id,'ATIVA',p_observacoes) returning * into x; perform public.bib_registrar_auditoria('RESERVA_CRIADA','RESERVA',x.id::text,to_jsonb(x)); return to_jsonb(x); end; $$;
revoke execute on function public.bib_registrar_reserva(integer,integer,text) from public,anon; grant execute on function public.bib_registrar_reserva(integer,integer,text) to authenticated;

create or replace function public.bib_renovar_emprestimo(p_emprestimo_id integer,p_dias integer default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,app_private as $$ declare x public.bib_emprestimos; cfg public.bib_configuracoes; tid uuid:=app_private.current_tenant_id(); dias integer; begin select * into x from public.bib_emprestimos where id=p_emprestimo_id and tenant_id=tid for update; if not found then raise exception 'Empréstimo não encontrado' using errcode='P0002'; end if; if x.status not in('ABERTO','PARCIAL') or x.prazo_devolucao<current_date then raise exception 'Empréstimo vencido ou encerrado não pode ser renovado' using errcode='22023'; end if; select * into cfg from public.bib_configuracoes where tenant_id=tid limit 1; if x.renovacoes>=coalesce(cfg.renovacoes_maximas,0) then raise exception 'Limite de renovações atingido' using errcode='22023'; end if; dias:=least(greatest(coalesce(p_dias,cfg.prazo_padrao_dias),1),coalesce(cfg.prazo_maximo_dias,30)); update public.bib_emprestimos set prazo_devolucao=greatest(prazo_devolucao,current_date)+dias,renovacoes=renovacoes+1,updated_at=now() where id=x.id returning * into x; perform public.bib_registrar_auditoria('EMPRESTIMO_RENOVADO','EMPRESTIMO',x.id::text,jsonb_build_object('novo_prazo',x.prazo_devolucao,'renovacoes',x.renovacoes)); return to_jsonb(x); end; $$;
revoke execute on function public.bib_renovar_emprestimo(integer,integer) from public,anon; grant execute on function public.bib_renovar_emprestimo(integer,integer) to authenticated;

create or replace function public.bib_registrar_bloqueio(p_leitor_id integer,p_motivo text,p_fim timestamptz default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,app_private as $$ declare x public.bib_bloqueios; begin if length(btrim(coalesce(p_motivo,'')))<5 then raise exception 'Informe o motivo do bloqueio' using errcode='22023'; end if; insert into public.bib_bloqueios(tenant_id,leitor_id,motivo,fim,criado_por) values(app_private.current_tenant_id(),p_leitor_id,btrim(p_motivo),p_fim,app_private.current_user_id()) returning * into x; perform public.bib_registrar_auditoria('LEITOR_BLOQUEADO','LEITOR',p_leitor_id::text,to_jsonb(x)); return to_jsonb(x); end; $$;
revoke execute on function public.bib_registrar_bloqueio(integer,text,timestamptz) from public,anon; grant execute on function public.bib_registrar_bloqueio(integer,text,timestamptz) to authenticated;

create or replace function public.bib_resolver_bloqueio(p_bloqueio_id bigint,p_motivo text default null) returns boolean language plpgsql security definer set search_path=pg_catalog,public,app_private as $$ begin update public.bib_bloqueios set ativo=false,resolvido_por=app_private.current_user_id(),resolvido_em=now(),updated_at=now(),motivo=case when p_motivo is null then motivo else motivo||' | Regularização: '||p_motivo end where id=p_bloqueio_id and tenant_id=app_private.current_tenant_id() and ativo; if not found then return false; end if; perform public.bib_registrar_auditoria('BLOQUEIO_RESOLVIDO','BLOQUEIO',p_bloqueio_id::text,jsonb_build_object('motivo',p_motivo)); return true; end; $$;
revoke execute on function public.bib_resolver_bloqueio(bigint,text) from public,anon; grant execute on function public.bib_resolver_bloqueio(bigint,text) to authenticated;

create or replace function public.bib_iniciar_inventario(p_nome text,p_escopo jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,app_private as $$ declare x public.bib_inventarios; begin insert into public.bib_inventarios(tenant_id,nome,escopo,status,iniciado_por) values(app_private.current_tenant_id(),coalesce(nullif(btrim(p_nome),''),'Inventário'),coalesce(p_escopo,'{}'::jsonb),'EM_EXECUCAO',app_private.current_user_id()) returning * into x; insert into public.bib_inventario_itens(tenant_id,inventario_id,exemplar_id,codigo_informado,situacao_encontrada) select app_private.current_tenant_id(),x.id,e.id,e.codigo,e.situacao from public.bib_exemplares e where e.tenant_id=app_private.current_tenant_id() and e.ativo; perform public.bib_registrar_auditoria('INVENTARIO_INICIADO','INVENTARIO',x.id::text,to_jsonb(x)); return to_jsonb(x); end; $$;
revoke execute on function public.bib_iniciar_inventario(text,jsonb) from public,anon; grant execute on function public.bib_iniciar_inventario(text,jsonb) to authenticated;

create or replace function public.bib_registrar_leitura_inventario(p_inventario_id bigint,p_codigo text,p_observacao text default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,app_private as $$ declare x public.bib_inventario_itens; e public.bib_exemplares; begin select * into e from public.bib_exemplares where tenant_id=app_private.current_tenant_id() and codigo=p_codigo limit 1; if not found then raise exception 'Exemplar não localizado' using errcode='P0002'; end if; update public.bib_inventario_itens set lido_em=now(),lido_por=app_private.current_user_id(),codigo_informado=p_codigo,situacao_encontrada=e.situacao,observacao=p_observacao,divergente=false where inventario_id=p_inventario_id and exemplar_id=e.id returning * into x; if not found then raise exception 'Exemplar não pertence ao inventário' using errcode='P0002'; end if; return to_jsonb(x); end; $$;
revoke execute on function public.bib_registrar_leitura_inventario(bigint,text,text) from public,anon; grant execute on function public.bib_registrar_leitura_inventario(bigint,text,text) to authenticated;

create or replace function public.bib_listar_notificacoes(p_apenas_nao_lidas boolean default false) returns setof jsonb language sql security invoker set search_path=pg_catalog,public,app_private as $$ select to_jsonb(n) from public.bib_notificacoes n where n.tenant_id=app_private.current_tenant_id() and n.usuario_id=app_private.current_user_id() and(not p_apenas_nao_lidas or n.lida_em is null) order by n.created_at desc limit 50; $$;
create or replace function public.bib_marcar_notificacao_lida(p_id uuid) returns boolean language plpgsql security invoker set search_path=pg_catalog,public,app_private as $$ begin update public.bib_notificacoes set lida_em=coalesce(lida_em,now()) where id=p_id and tenant_id=app_private.current_tenant_id() and usuario_id=app_private.current_user_id(); return found; end; $$;
revoke execute on function public.bib_listar_notificacoes(boolean),public.bib_marcar_notificacao_lida(uuid) from public,anon; grant execute on function public.bib_listar_notificacoes(boolean),public.bib_marcar_notificacao_lida(uuid) to authenticated;
